(() => {
'use strict';
const $=id=>document.getElementById(id), C=window.MathCurriculum;
let session=null, questions=[], onChange=()=>{};
const labels=['Easy','Medium','Hard'];
const earned=()=>session?session.answers.filter(a=>a.correct).length*2:0;
function populate(){const g=Number($('grade').value);$('subject').replaceChildren(...C.grades[g].map(([value,label])=>new Option(label,value)));}
for(let g=1;g<=11;g++)$('grade').add(new Option(`Grade ${g}`,g));
const requestedGrade=Number(new URLSearchParams(location.search).get('grade'));$('grade').value=String(Number.isInteger(requestedGrade)&&requestedGrade>=1&&requestedGrade<=11?requestedGrade:3);populate();$('grade').onchange=populate;
function title(){return `Grade ${session.grade} · ${C.grades[session.grade].find(t=>t[0]===session.topic)[1]} · ${labels[session.difficulty]}`;}
function render(){
 const panel=$('math-panel');panel.hidden=!session;$('welcome').hidden=!!session;$('coins').textContent=earned();if(!session)return;
 const index=session.answers.length, answered=session.phase==='feedback',complete=index===20&&!answered,qi=answered?index-1:index,q=questions[qi];
 let html=`<div class="math-heading"><div><p class="eyebrow">ROBOT TRAINING · ${title()}</p><h2>${complete?'Level complete!':`Customer challenge ${qi+1} of 20`}</h2></div><span class="math-score">${earned()/2} correct · +${earned()} coins</span></div><progress max="20" value="${index}" aria-label="Questions answered">${index}/20</progress>`;
 if(complete){const wrong=session.answers.map((a,i)=>({...a,q:questions[i]})).filter(a=>!a.correct);html+=`<p>You answered <b>${earned()/2}/20</b> correctly and earned <b>${earned()} bonus coins</b> for your robot crew. Use Change level to practise another subject or difficulty. Starting a level resets its coins.</p><h3>Your learning review</h3>${wrong.length?'<p>Revisit these questions:</p><ol class="review">'+wrong.map(a=>`<li><b>${a.q.text}</b><p>Your answer: ${a.value}. Correct answer: ${a.q.answer}. ${a.q.explanation}</p></li>`).join('')+'</ol>':'<p>Perfect accuracy! Try a harder difficulty or a new subject.</p>'}`;}
 else {html+=QuestionArt.render(q,session,qi);html+=`<p class="question-text">${q.text}</p><p class="hint">Type a number. You may use a calculator. Round to 2 decimal places when requested.</p>`;if(answered){const last=session.answers.at(-1);html+=`<div class="math-feedback ${last.correct?'correct':'incorrect'}"><strong>${last.correct?'Correct! +2 shop coins':'Let’s work it through.'}</strong><p>Your answer: ${last.value}. Correct answer: <b>${q.answer}</b>.</p><p>${q.explanation}</p></div><button class="primary" id="math-next">${index===20?'See level results':'Next question'} →</button>`;}else html+='<form id="math-answer-form"><label for="math-answer">Your answer</label><div class="answer"><input id="math-answer" type="text" inputmode="decimal" autocomplete="off" maxlength="30" placeholder="?" required><button class="primary" type="submit">Check answer →</button></div><p id="math-error" role="alert"></p></form>';}
 panel.innerHTML=html; if($('replay-art'))$('replay-art').onclick=()=>{const svg=panel.querySelector('.question-art svg');svg.replaceWith(svg.cloneNode(true));};
 if($('math-answer-form'))$('math-answer-form').onsubmit=e=>{e.preventDefault();let raw=$('math-answer').value.trim().replaceAll('−','-');if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(raw)||!Number.isFinite(Number(raw))){$('math-error').textContent='Enter a number, such as 12, −3 (using the minus key), or 0.25.';return;}const value=Number(raw);session.answers.push({value,correct:Math.abs(value-q.answer)<0.000001});session.phase='feedback';render();onChange();$('math-next').focus();};
 if($('math-next'))$('math-next').onclick=()=>{session.phase='question';render();$('math-answer')?.focus();};
}
$('teacher-form').onsubmit=e=>{e.preventDefault();start();};
function start(){session={grade:Number($('grade').value),topic:$('subject').value,difficulty:Number($('difficulty').value),phase:'question',answers:[]};questions=C.bank(session.grade,session.topic,session.difficulty);$('setup-modal').close();render();onChange();$('math-answer').focus();}
function validate(s){if(s===null||s===undefined)return null;if(!Number.isInteger(s.grade)||!C.grades[s.grade]?.some(t=>t[0]===s.topic)||![0,1,2].includes(s.difficulty)||!['question','feedback'].includes(s.phase)||!Array.isArray(s.answers)||s.answers.length>20||s.phase==='feedback'&&!s.answers.length)throw Error('Invalid maths level');const bank=C.bank(s.grade,s.topic,s.difficulty);const answers=s.answers.map((a,i)=>{if(!a||!Number.isFinite(a.value)||typeof a.correct!=='boolean'||a.correct!==(Math.abs(a.value-bank[i].answer)<0.000001))throw Error('Invalid maths answer');return {value:a.value,correct:a.correct};});return {grade:s.grade,topic:s.topic,difficulty:s.difficulty,phase:s.phase,answers};}
window.MathLab={earned,validate,snapshot:()=>session?JSON.parse(JSON.stringify(session)):null,restore:s=>{session=validate(s);questions=session?C.bank(session.grade,session.topic,session.difficulty):[];if(session){$('grade').value=session.grade;populate();$('subject').value=session.topic;$('difficulty').value=session.difficulty;}render();},subscribe:fn=>{onChange=fn;},text:()=>session?{grade:session.grade,topic:session.topic,difficulty:labels[session.difficulty],answered:session.answers.length,phase:session.phase,question:questions[session.phase==='feedback'?session.answers.length-1:session.answers.length]?.text,bonus:earned()}:null};
})();

// The maths adventure is the sole game; files store a validated level snapshot.
(() => {
const $=id=>document.getElementById(id);let pending=null;
function setup(){$('cancel-setup').hidden=!MathLab.snapshot();$('setup-modal').showModal();}
$('change-level').onclick=setup;$('choose').onclick=setup;$('cancel-setup').onclick=()=>$('setup-modal').close();
$('setup-modal').addEventListener('cancel',e=>{if(!MathLab.snapshot())e.preventDefault();});
function show(html){$('modal-content').innerHTML=html;$('modal').showModal();}
$('close').onclick=()=>{$('modal').close();pending=null;};
$('guide').onclick=()=>show('<h2>See it. Solve it.</h2><p>Choose Grade 1–11, a maths subject and Easy, Medium or Hard. Study the illustrated model, type your answer and check the explanation. Each correct answer earns 2 coins. Complete 20 questions to see your score and review missed questions.</p><p>Change level opens the selector. Starting a new level resets the current level. Save your progress to return later. Use Replay visual to see an animation again. Some diagrams use a labelled sample when quantities are too large to count individually.</p><p>Keyboard: Tab to move, Enter to select; F toggles fullscreen. Esc exits fullscreen or closes a dialog.</p>');
$('save').onclick=()=>{if(!MathLab.snapshot()){show('<h2>Choose a level first.</h2><p>Start a level to save its progress.</p>');return;}const url=URL.createObjectURL(new Blob([JSON.stringify({version:2,math:MathLab.snapshot()},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='robot-maths-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('load').onclick=()=>$('file').click();$('file').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{if(f.size>20000)throw Error();const data=JSON.parse(await f.text());if(![1,2].includes(data.version)||!data.math)throw Error();pending=MathLab.validate(data.math);const name=MathCurriculum.grades[pending.grade].find(t=>t[0]===pending.topic)[1];show(`<h2>Resume this adventure?</h2><p>Grade ${pending.grade} · ${name} · ${['Easy','Medium','Hard'][pending.difficulty]}<br>${pending.answers.length}/20 answered · ${pending.answers.filter(a=>a.correct).length*2} coins</p><p>This replaces the current level.</p><button class="primary" id="confirm-load">Load this level</button>`);}catch{pending=null;show('<h2>That save could not be loaded.</h2><p>Choose a valid Robot Maths save. Your current level has been kept.</p>');}};
$('modal-content').onclick=e=>{if(e.target.id==='confirm-load'&&pending){MathLab.restore(pending);pending=null;$('modal').close();}};
MathLab.subscribe(()=>{});document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='f'&&!['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)){if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.();}});
window.render_game_to_text=()=>JSON.stringify({mode:MathLab.snapshot()?'maths':'setup',math:MathLab.text(),coins:MathLab.earned(),visual:document.querySelector('.question-art')?.dataset.visual,coordinateSystem:'SVG viewBox 780 × 350; origin top-left, x right, y down'});window.advanceTime=()=>{};setup();
})();
